import{_ as e,o,c as a,ag as n}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 1 Lab — Hello, Web","description":"","frontmatter":{"source":"weeks/01-hello-vibe-coding/lab.md"},"headers":[],"relativePath":"weeks/01-hello-vibe-coding/lab.md","filePath":"weeks/01-hello-vibe-coding/lab.md"}'),s={name:"weeks/01-hello-vibe-coding/lab.md"};function r(i,t,d,h,l,c){return o(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="week-1-lab--hello-web" tabindex="-1">Week 1 Lab — Hello, Web <a class="header-anchor" href="#week-1-lab--hello-web" aria-label="Permalink to &quot;Week 1 Lab — Hello, Web&quot;">​</a></h1><blockquote><p><strong>Goal:</strong> in Studio A, build a one-file personal home page with an AI and save it. In Studio B, have the AI explain it section by section, then change its HTML, CSS and JavaScript by hand. <strong>Time:</strong> two 75-minute studios, with about 40 minutes of lab in each. <strong>You need:</strong> a laptop, your personal Google account, and the privacy settings from week 0. Next week you publish the page on GitHub.</p></blockquote><p><strong>AI-use key:</strong> 🟢 AI on: use AI freely · 🟡 AI limited: the AI may comment or hint, but the work is yours · 🔴 AI off: close the AI tabs and work alone.</p><p>Studios are graded on effort, not polish (<a href="./../../assessment/rubrics.html#labs">rubric</a>): a part that didn&#39;t work, with the exact error and what you tried, still counts.</p><p>You use the simplest version of the course workflow: <strong>describe → generate → run → customize</strong>. You describe the page, the AI generates the code, you run it in the live preview, and then you customize it one change at a time.</p><p>Stuck for more than 5 minutes? Check <a href="#troubleshooting">Troubleshooting</a>, ask a neighbor, then raise your hand. Using a screen reader or only a keyboard? See the <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a>; if a chat tool&#39;s code view is hard to use, the local-file route in <a href="#no-preview-run-it-yourself">No preview? Run it yourself</a> lets you work in your own editor.</p><hr><h2 id="studio-a--build-your-page-75-min" tabindex="-1">Studio A — Build your page (75 min) <a class="header-anchor" href="#studio-a--build-your-page-75-min" aria-label="Permalink to &quot;Studio A — Build your page (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What you do</th><th>Time</th><th>Core or If time</th><th>AI use</th></tr></thead><tbody><tr><td>A1</td><td>Privacy check</td><td>5 min</td><td>Core</td><td>Not needed</td></tr><tr><td>A2</td><td>Build &quot;Hello, Web&quot;</td><td>25 min</td><td>Core</td><td>🟢 AI on</td></tr><tr><td>A3</td><td>Save your work</td><td>10 min</td><td>Core</td><td>Not needed</td></tr><tr><td>A4</td><td>Keep customizing, or try a second assistant</td><td>any spare time</td><td>If time</td><td>🟢 AI on</td></tr></tbody></table><p>Before the lab: a welcome, the concept talk and a live demo (30 minutes). The studio ends with a <strong>checkpoint share</strong>: show a neighbor your page and the prompt that changed it most.</p><h3 id="part-a1--privacy-check-5-min" tabindex="-1">Part A1 — Privacy check (5 min) <a class="header-anchor" href="#part-a1--privacy-check-5-min" aria-label="Permalink to &quot;Part A1 — Privacy check (5 min)&quot;">​</a></h3><p><strong>Why:</strong> free AI tools may store your chats, train on them and let human reviewers read samples. You set the privacy settings in week 0; now check they stuck.</p><ol><li>In one browser tab, open the <a href="./../../setup/privacy-settings.html">Privacy settings</a> page.</li><li>In another tab, sign in to <strong>Gemini</strong> at <code>gemini.google.com</code> with your <strong>personal</strong> Google account. A school or work account may block Gemini or hide its Canvas tool.</li><li>Check that Gemini&#39;s <strong>Keep Activity</strong> is off, as described in the <a href="./../../setup/privacy-settings.html#gemini">Gemini section</a>. If you plan to use a fallback (ChatGPT or Claude), check its setting too.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>With Keep Activity off, Gemini doesn&#39;t keep your chats: when you close the tab, the chat is gone, and you can&#39;t reopen it or share a link to it later. That&#39;s fine. In Part A3 you save your code and prompts yourself.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Your page will be <strong>public</strong> from next week. Use your first name or a nickname. Do not put your surname, email, phone number, address, student ID or anything about other people into the page, and do not paste any of it into the AI.</p></div><p>✅ <strong>Checkpoint:</strong> you are signed in to Gemini with a personal account, and Keep Activity is off.</p><h3 id="part-a2--build-hello-web-25-min" tabindex="-1">Part A2 — Build &quot;Hello, Web&quot; (25 min) <a class="header-anchor" href="#part-a2--build-hello-web-25-min" aria-label="Permalink to &quot;Part A2 — Build &quot;Hello, Web&quot; (25 min)&quot;">​</a></h3><p>🟢 AI on.</p><h4 id="open-the-live-preview" tabindex="-1">Open the live preview <a class="header-anchor" href="#open-the-live-preview" aria-label="Permalink to &quot;Open the live preview&quot;">​</a></h4><ol><li>In Gemini, start a <strong>new chat</strong>.</li><li>Turn on <strong>Canvas</strong>: look for it under <strong>Tools</strong> (or a <strong>+</strong> menu) in the prompt box. A <a href="./../../resources/glossary.html#live-preview">live preview</a> shows the page running next to the chat.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Menus move. If you can&#39;t find Canvas, start your prompt with &quot;Use Canvas to…&quot;, or ask Gemini where Canvas is. Using a fallback? Claude shows a live preview called an <strong>Artifact</strong> (18+ only); with ChatGPT, see <a href="#no-preview-run-it-yourself">No preview? Run it yourself</a>. Your instructor tells you which tool leads this week.</p></div><h4 id="your-first-prompt" tabindex="-1">Your first prompt <a class="header-anchor" href="#your-first-prompt" aria-label="Permalink to &quot;Your first prompt&quot;">​</a></h4><p>A good prompt has four parts: <strong>Goal · Context · Constraints · Done when</strong>. You&#39;ll study them properly in week 3; for now, fill in the blanks. Replace everything in <code>[square brackets]</code>. More starters: <a href="./prompt-starters.html">Prompt starters</a>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Make a one-page personal home page about me that I will publish on the web.</span></span>
<span class="line"><span>Context: I&#39;m in a course called Building Apps with AI. I know some Python, but I&#39;m new to HTML, CSS and JavaScript. The page is for classmates and friends. About me: my name is [first name or nickname]. I&#39;m interested in [interest 1], [interest 2] and [interest 3]. Right now I&#39;m learning [something]. I like the colors [color 1] and [color 2].</span></span>
<span class="line"><span>Constraints: One single HTML file with the CSS and JavaScript inside it. No frameworks, no libraries, no external images or fonts. It must look good on a phone and on a laptop. Keep the code readable, with a short comment at the start of each section. Do not add an email address, phone number, surname or social-media links.</span></span>
<span class="line"><span>Done when: The preview shows my name as a big heading, a short &quot;About me&quot; paragraph, a list of my interests, and one button that shows a random fun fact about me, picked from a list of five, each time I click it.</span></span></code></pre></div><p>Send it. Gemini writes the code and shows it in the Canvas panel. Look for a <strong>Preview</strong> view (the page) and a <strong>Code</strong> view (the text that makes it). Copy the prompt into a <strong>scratch note</strong> (paper or a notes app); next week it becomes your first entry in <code>PROMPTS.md</code>.</p><p>✅ <strong>Checkpoint:</strong> the preview shows a page with your name as a heading, an &quot;About me&quot; section, your interests and a button. Click it a few times. A fact appears, and it changes.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Your page looks different from your neighbor&#39;s even with the same prompt. That&#39;s normal: the model picks among likely answers, so each run differs.</p></div><h4 id="customize-at-least-3-iterations" tabindex="-1">Customize: at least 3 iterations <a class="header-anchor" href="#customize-at-least-3-iterations" aria-label="Permalink to &quot;Customize: at least 3 iterations&quot;">​</a></h4><p>Now improve the page <strong>one change per prompt</strong>. Small, specific requests beat &quot;make it better&quot;, and when something breaks you know which change did it. In your scratch note, write down each prompt and what happened.</p><p>Use these, the <a href="./prompt-starters.html#customization-prompts">customization prompts</a> (phone layout, footer, fonts, animation), or your own:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Change the color scheme.</span></span>
<span class="line"><span>Context: The page you just made.</span></span>
<span class="line"><span>Constraints: Keep everything else the same. Make sure text is easy to read against the background.</span></span>
<span class="line"><span>Done when: The background and headings use [color] and [color], and all text is still readable.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Add a &quot;Things I&#39;m learning&quot; section with three short items.</span></span>
<span class="line"><span>Context: The page you just made. The items are: [item], [item], [item].</span></span>
<span class="line"><span>Constraints: Match the style of the existing sections. Don&#39;t change other sections.</span></span>
<span class="line"><span>Done when: The new section appears below &quot;About me&quot; and looks like it belongs.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Make the fun-fact button more fun.</span></span>
<span class="line"><span>Context: Right now the button shows a random fact from a list.</span></span>
<span class="line"><span>Constraints: Plain JavaScript only, no libraries. Keep the list of facts where it is.</span></span>
<span class="line"><span>Done when: Clicking the button [describe what you want: e.g. makes the fact fade in, or changes the button&#39;s label to &quot;Another one!&quot;], every time it&#39;s clicked.</span></span></code></pre></div><p>Before each prompt, <strong>predict</strong> what will change; afterwards, check the preview against your &quot;Done when&quot;. If a change makes things worse, say so: &quot;That broke the layout on narrow screens. Undo that change.&quot;</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If the AI keeps failing at the same thing after <strong>two</strong> attempts, stop. Start a fresh chat, paste your current code, and describe the problem more precisely. That&#39;s the <a href="./../../resources/glossary.html#two-strikes-rule"><strong>two-strikes rule</strong></a>, and you&#39;ll use it all course.</p></div><p><strong>Don&#39;t close the chat tab</strong> until Part A3 is done: with Keep Activity off, a closed tab is a lost chat. (Lost it anyway? Start a fresh chat with the same first prompt. The second build goes faster.)</p><p>✅ <strong>Checkpoint:</strong> you have sent at least 3 customization prompts, the preview shows your improved page, and your scratch note lists what each prompt did.</p><h3 id="no-preview-run-it-yourself" tabindex="-1">No preview? Run it yourself <a class="header-anchor" href="#no-preview-run-it-yourself" aria-label="Permalink to &quot;No preview? Run it yourself&quot;">​</a></h3><p>If your assistant shows code but no live preview (see the <a href="./../../TOOLS.html">Tool Handout</a>), run the code yourself. You&#39;ll use the same steps in Studio B. Use the <strong>copy</strong> button on the code block so you get exactly the code, without extra lines such as <code>\`\`\`html</code>.</p><ol><li>Open a plain-text editor: <strong>Notepad</strong> on Windows, <strong>TextEdit</strong> on a Mac (then choose <strong>Format → Make Plain Text</strong>), the <strong>Text</strong> app on a Chromebook, or a code editor you already use, such as VS Code. Not Word or Google Docs: they add formatting the browser can&#39;t read.</li><li>Paste the code and save it as <code>index.html</code> (on Windows, set &quot;Save as type&quot; to <strong>All files</strong>).</li><li>Double-click the file to open it in your browser.</li><li>After each change, paste the new code (or type your edit), save, and refresh the browser.</li></ol><p>Want your page online straight away? The publishing steps are in <a href="./../02-ship-your-page/lab.html">week 2&#39;s lab</a>, and they work any time.</p><h3 id="part-a3--save-your-work-10-min" tabindex="-1">Part A3 — Save your work (10 min) <a class="header-anchor" href="#part-a3--save-your-work-10-min" aria-label="Permalink to &quot;Part A3 — Save your work (10 min)&quot;">​</a></h3><p><strong>Why:</strong> Studio B starts from your file, and the chat won&#39;t be there any more. Your code and your notes must be.</p><ol><li><strong>Get the file.</strong><ul><li>If your tool has a <strong>Download</strong> button, download the file. Check its name: it must be exactly <code>index.html</code> (all lowercase). Rename it if it&#39;s <code>index (1).html</code>, <code>Untitled.html</code> or <code>index.html.txt</code>.</li><li>If there&#39;s no download, open the <strong>Code</strong> view, use its copy button (or click in the code, then <strong>Ctrl+A</strong> / <strong>Cmd+A</strong> and copy), and save the code as <code>index.html</code> with the steps in <a href="#no-preview-run-it-yourself">No preview? Run it yourself</a>.</li></ul></li><li><strong>Check it.</strong> Double-click <code>index.html</code>. Your page opens in the browser, and the button works.</li><li><strong>Keep it where you&#39;ll find it</strong>: the Desktop or Documents folder (on a Chromebook, <strong>My files</strong>). Can&#39;t save files on this computer? Paste the code into a private document you can open in Studio B.</li><li><strong>Keep your scratch note</strong>: your first prompt, and the customization prompt that worked best (or went most wrong).</li></ol><p>✅ <strong>Checkpoint:</strong> <code>index.html</code> opens in your browser from your computer, and your scratch note is safe.</p><h3 id="part-a4--keep-customizing-or-try-a-second-assistant-if-time" tabindex="-1">Part A4 — Keep customizing, or try a second assistant (if time) <a class="header-anchor" href="#part-a4--keep-customizing-or-try-a-second-assistant-if-time" aria-label="Permalink to &quot;Part A4 — Keep customizing, or try a second assistant (if time)&quot;">​</a></h3><p>🟢 AI on. Pick one:</p><ul><li><strong>More iterations.</strong> Add a footer, a phone layout or an animation from the <a href="./prompt-starters.html#customization-prompts">customization prompts</a>. Save <code>index.html</code> again afterwards (Part A3).</li><li><strong>Same prompt, second assistant.</strong> Send your first prompt, unchanged, to a second assistant from the <a href="./../../TOOLS.html">Tool Handout</a>. How different is the result? How many lines is each?</li></ul><h3 id="checkpoint-share-end-of-studio-a" tabindex="-1">Checkpoint share (end of Studio A) <a class="header-anchor" href="#checkpoint-share-end-of-studio-a" aria-label="Permalink to &quot;Checkpoint share (end of Studio A)&quot;">​</a></h3><p>Show a neighbor your page and read them the prompt that changed it most. If your instructor asks, post a screenshot of your page where they say (crop out other tabs and anything personal). Stuck? Share the exact blocker instead: that counts too.</p><p><strong>Working alone?</strong> Write one sentence in your scratch note: which prompt changed your page most, and how.</p><hr><h2 id="studio-b--explain-it-change-it-by-hand-75-min" tabindex="-1">Studio B — Explain it, change it by hand (75 min) <a class="header-anchor" href="#studio-b--explain-it-change-it-by-hand-75-min" aria-label="Permalink to &quot;Studio B — Explain it, change it by hand (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What you do</th><th>Time</th><th>Core or If time</th><th>AI use</th></tr></thead><tbody><tr><td>Mini-lesson</td><td>Reading a page as a programmer</td><td>5 min</td><td>Core</td><td>Not needed</td></tr><tr><td>B1</td><td>Take a guided tour of your code</td><td>15 min</td><td>Core</td><td>🟢 AI on</td></tr><tr><td>B2</td><td>Change it by hand</td><td>20 min</td><td>Core</td><td>🔴 AI off</td></tr><tr><td>B3</td><td>Save and log</td><td>5 min</td><td>Core</td><td>Not needed</td></tr><tr><td>B4</td><td>Break it on purpose, or start the homework</td><td>15 min</td><td>If time</td><td>🔴 AI off for the breaks</td></tr></tbody></table><p>The studio opens with show and tell. Part B4 is also project time: catch up on B1–B3 first if you&#39;re behind. The studio ends with the Week 1 exit ticket (🔴 AI off).</p><p><strong>Set up first.</strong> Open your saved <code>index.html</code> in two places, side by side: your <strong>browser</strong> (double-click it) and a <strong>text editor</strong> (as in <a href="#no-preview-run-it-yourself">No preview? Run it yourself</a>). After each edit: save in the editor, refresh in the browser. No file? Paste your saved code into a new Gemini chat with Canvas on, ask &quot;Show this code in Canvas without changing it&quot;, and work in its Code view.</p><h3 id="mini-lesson--reading-a-page-as-a-programmer-5-min" tabindex="-1">Mini-lesson — Reading a page as a programmer (5 min) <a class="header-anchor" href="#mini-lesson--reading-a-page-as-a-programmer-5-min" aria-label="Permalink to &quot;Mini-lesson — Reading a page as a programmer (5 min)&quot;">​</a></h3><p>You already know what a variable, a list and a function are. What&#39;s new is where they live:</p><ul><li><strong>HTML</strong> is made of <a href="./../../resources/glossary.html#element">elements</a>: an opening tag, content, a closing tag, as in <code>&lt;li&gt;Hiking&lt;/li&gt;</code>. Extra settings inside the opening tag are <strong>attributes</strong>: <code>&lt;button id=&quot;fact-button&quot;&gt;</code>.</li><li><strong>CSS</strong> is a list of rules: a <strong>selector</strong> saying what to style, then declarations in braces. <code>button { background: teal; }</code> styles every button.</li><li><strong>JavaScript</strong> finds an element (<code>document.getElementById(&quot;fact-button&quot;)</code>) and attaches an <a href="./../../resources/glossary.html#event-and-event-listener">event listener</a>: a function the browser calls when something happens, such as a click.</li></ul><p>Where JavaScript trips up Python programmers in a page like yours:</p><table tabindex="0"><thead><tr><th>In your page&#39;s JavaScript</th><th>The Python you know</th></tr></thead><tbody><tr><td><code>const facts = [&quot;…&quot;, &quot;…&quot;];</code> (<code>let</code> if you&#39;ll reassign it)</td><td><code>facts = [&quot;…&quot;, &quot;…&quot;]</code></td></tr><tr><td><code>facts.length</code></td><td><code>len(facts)</code></td></tr><tr><td><code>facts.push(&quot;…&quot;)</code></td><td><code>facts.append(&quot;…&quot;)</code></td></tr><tr><td>Blocks use <code>{ }</code>; indentation is only for people</td><td>Indentation <em>is</em> the block</td></tr><tr><td><code>===</code> to compare (JavaScript&#39;s <code>==</code> converts types first; avoid it)</td><td><code>==</code></td></tr></tbody></table><p>The full comparison is in <a href="./../../setup/python-to-javascript.html">From Python to JavaScript</a>.</p><h3 id="part-b1--take-a-guided-tour-of-your-code-15-min" tabindex="-1">Part B1 — Take a guided tour of your code (15 min) <a class="header-anchor" href="#part-b1--take-a-guided-tour-of-your-code-15-min" aria-label="Permalink to &quot;Part B1 — Take a guided tour of your code (15 min)&quot;">​</a></h3><p>🟢 AI on.</p><p><strong>Why:</strong> right now the page works and you don&#39;t know why. &quot;If you can&#39;t explain it, you didn&#39;t build it.&quot; This part is where you start to own it.</p><p>Start a <strong>new chat</strong> and paste your whole file: the AI doesn&#39;t remember Studio A.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Help me understand the page in the code below.</span></span>
<span class="line"><span>Context: I know some Python, but I&#39;m new to HTML, CSS and JavaScript. Here is my page: [paste the complete index.html]</span></span>
<span class="line"><span>Constraints: Don&#39;t change the code. Go through it section by section, from top to bottom. For each section, quote its first line, label it HTML (structure), CSS (style) or JavaScript (behavior), and explain in one or two plain-English sentences what it does. Where the JavaScript works differently from Python, say how in one line.</span></span>
<span class="line"><span>Done when: I could point at any part of the page in the browser and find the code that makes it.</span></span></code></pre></div><p>Read the answer with your editor open next to it. For each section, find it in the code and on the page.</p><p>Then ask at least <strong>one follow-up</strong> about something you don&#39;t understand, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What does the line starting with &quot;[paste the line]&quot; do? What would happen if I changed it to [this]? Predict it, then tell me how I can check.</span></span></code></pre></div><p><strong>Check the tour.</strong> Explanations can be wrong too. Pick one claim the AI made (&quot;this rule sets the heading color&quot;) and test it in Part B2.</p><p>✅ <strong>Checkpoint:</strong> you can point to (1) the HTML for your heading, (2) the CSS rule that sets the background color, (3) the list of facts in the JavaScript, and (4) the function that runs when the button is clicked.</p><h3 id="part-b2--change-it-by-hand-20-min" tabindex="-1">Part B2 — Change it by hand (20 min) <a class="header-anchor" href="#part-b2--change-it-by-hand-20-min" aria-label="Permalink to &quot;Part B2 — Change it by hand (20 min)&quot;">​</a></h3><p>🔴 AI off. Close the AI tabs. You may use your file, the browser, the <a href="./../../setup/python-to-javascript.html">bridge page</a> and <a href="https://developer.mozilla.org/en-US/docs/Web" target="_blank" rel="noreferrer">MDN</a>, the standard web reference. Skip the AI summaries search engines put above their results: they count as AI.</p><p>Make these four changes, one at a time. <strong>Predict</strong> what you&#39;ll see before you refresh.</p><table tabindex="0"><thead><tr><th>#</th><th>Language</th><th>Change</th><th>Example</th></tr></thead><tbody><tr><td>1</td><td>HTML</td><td>Add one element: another item in a list, or a new paragraph in a section</td><td><code>&lt;li&gt;Rock climbing&lt;/li&gt;</code></td></tr><tr><td>2</td><td>CSS</td><td>Change a color or a size in an existing rule</td><td><code>background: #f5f5f5;</code> → <code>background: lavender;</code></td></tr><tr><td>3</td><td>CSS</td><td>Add a new rule: a hover style for your button</td><td><code>button:hover { background: navy; }</code></td></tr><tr><td>4</td><td>JavaScript</td><td>Add a sixth fact to the button&#39;s list (an array: JavaScript&#39;s list), then click until it appears</td><td><code>&quot;I&#39;ve hiked in three countries.&quot;,</code></td></tr></tbody></table><p>Colors to try: <code>tomato</code>, <code>gold</code>, <code>seagreen</code>, <code>rebeccapurple</code>, <code>lavender</code>, <code>navy</code>.</p><p><strong>Done early?</strong> Make the button count: show &quot;Fact 4 of your visit&quot; (or similar) above the fact. You&#39;ll need a counter declared with <code>let</code> outside the click function, a <code>+= 1</code> inside it, and <code>textContent</code> to show it.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If something breaks, undo with <strong>Ctrl+Z</strong> (Windows, ChromeOS) or <strong>Cmd+Z</strong> (Mac). A missing <code>;</code>, <code>}</code>, <code>&gt;</code>, comma or quote mark is the usual cause. Broken HTML or CSS usually still shows <em>something</em>; one typo in the JavaScript stops the whole script, so the button goes dead. (The browser&#39;s <strong>Console</strong> shows the error message. You&#39;ll learn to read it in week 7.)</p></div><p>In your scratch note, write down each change: what you changed, from what to what, and what happened. Next week they go into the <strong>Ownership statement</strong> of your <code>PROMPTS.md</code> (what you wrote or decided yourself).</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The AI can&#39;t see edits you make outside its chat. If you edit the file and then want the AI to make another change, paste your current code into the chat first. That&#39;s the <strong>context window</strong> from the concept talk. (Edits typed into Gemini&#39;s Canvas are usually visible to Gemini; if it seems to ignore them, paste the code back in.)</p></div><p>✅ <strong>Checkpoint:</strong> the browser shows all four changes, the button still works (with your new fact in its list), and you can say which line you changed for each.</p><h3 id="part-b3--save-and-log-5-min" tabindex="-1">Part B3 — Save and log (5 min) <a class="header-anchor" href="#part-b3--save-and-log-5-min" aria-label="Permalink to &quot;Part B3 — Save and log (5 min)&quot;">​</a></h3><ol><li>Save <code>index.html</code>, close it, and double-click it once more to check it opens with all your changes.</li><li>Upload it to <strong>Canvas</strong>, the course&#39;s learning management system (not Gemini&#39;s Canvas tool), as the assignment &quot;Week 1 page&quot;. Until your page is on GitHub next week, that copy is your backup. You can upload again later in the week.</li><li>Check your scratch note has your prompts and all four hand changes.</li></ol><p>✅ <strong>Checkpoint:</strong> your latest <code>index.html</code> is on Canvas, and your scratch note lists every change you made by hand.</p><h3 id="part-b4--break-it-on-purpose-or-start-the-homework-15-min-if-time" tabindex="-1">Part B4 — Break it on purpose, or start the homework (15 min, if time) <a class="header-anchor" href="#part-b4--break-it-on-purpose-or-start-the-homework-15-min-if-time" aria-label="Permalink to &quot;Part B4 — Break it on purpose, or start the homework (15 min, if time)&quot;">​</a></h3><p>🔴 AI off for the breaks. Pick one:</p><ul><li><strong>Break it on purpose.</strong> One at a time, and undo each before the next: delete one <code>}</code> in the <code>&lt;style&gt;</code> section; delete one <code>&gt;</code> from an HTML tag; delete one <code>)</code> in the <code>&lt;script&gt;</code> section. Refresh after each and note what happens. Browsers try hard to show <em>something</em> for broken HTML and CSS, which is why broken code can look almost right; broken JavaScript simply stops.</li><li><strong>Start homework task 2:</strong> a small feature written entirely by hand (<a href="./homework.html">homework</a>).</li></ul><h3 id="before-you-leave-studio-b" tabindex="-1">Before you leave Studio B <a class="header-anchor" href="#before-you-leave-studio-b" aria-label="Permalink to &quot;Before you leave Studio B&quot;">​</a></h3><ul><li>☐ <code>index.html</code> with your hand changes is saved on your computer and uploaded to Canvas.</li><li>☐ Your scratch note has your prompts and your hand changes.</li><li>☐ You did the Week 1 exit ticket (🔴 AI off). It&#39;s scored for completion, not correctness.</li><li>☐ You know what&#39;s in the <a href="./homework.html">homework</a>, including the first half of the AI Fluency course.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>Gemini says Canvas or Gemini isn&#39;t available</td><td>School or work Google account</td><td>Sign out and use a personal Google account</td></tr><tr><td>No Canvas option anywhere</td><td>Menu moved, or the feature is rolling out differently</td><td>Start the prompt with &quot;Use Canvas to…&quot;; otherwise use a fallback (see below)</td></tr><tr><td>You closed the chat tab and the chat is gone</td><td>Keep Activity is off, so Gemini doesn&#39;t keep chats</td><td>Expected. Use your saved <code>index.html</code> (Part A3): start a new chat and paste it in</td></tr><tr><td>The preview is blank</td><td>An error in the code, or it used an outside file</td><td>Ask: &quot;The preview is blank. Check the code for errors and make sure it&#39;s one file with no external files.&quot;</td></tr><tr><td>The tool used React or another framework</td><td>Some tools pick one by themselves</td><td>Ask again: &quot;One HTML file, no frameworks, no libraries.&quot; A framework file won&#39;t open by double-clicking</td></tr><tr><td>The preview works, but there&#39;s no Download button</td><td>Not every tool has one</td><td>Copy the code and save it yourself (<a href="#no-preview-run-it-yourself">No preview? Run it yourself</a>)</td></tr><tr><td>Double-clicking opens the file in an editor, or as plain text</td><td>The name ends in <code>.txt</code> (Windows may hide it), or the file starts with <code>\`\`\`</code></td><td>Rename it to exactly <code>index.html</code>; delete any <code>\`\`\`</code> lines at the top and bottom</td></tr><tr><td>The page looks different from the preview</td><td>The preview loaded something your file doesn&#39;t include</td><td>Ask the AI to &quot;put everything in one file with no external files or images&quot;, then save again</td></tr><tr><td>Your hand edit doesn&#39;t show</td><td>Not saved, or the browser shows the old version</td><td>Save in the editor, then <a href="./../../resources/glossary.html#hard-reload">hard-reload</a>: <strong>Ctrl+Shift+R</strong> (Windows, ChromeOS) or <strong>Cmd+Shift+R</strong> (Mac)</td></tr><tr><td>The button stopped working after your edit</td><td>A typo in the JavaScript stops the whole script</td><td>Undo your last change, or check the line you edited for a missing comma, quote mark or bracket</td></tr><tr><td>The AI &quot;forgot&quot; your hand changes</td><td>It can&#39;t see edits outside its chat</td><td>Paste your current code into the chat first</td></tr><tr><td>You hit a usage limit in the assistant</td><td>Free tiers have limits (see the <a href="./../../TOOLS.html">Tool Handout</a>)</td><td>Switch to a fallback and paste in your current code. See <a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a></td></tr></tbody></table><p>More fixes: <a href="./../../resources/troubleshooting.html">Troubleshooting</a>.</p><h2 id="if-your-tool-is-down" tabindex="-1">If your tool is down <a class="header-anchor" href="#if-your-tool-is-down" aria-label="Permalink to &quot;If your tool is down&quot;">​</a></h2><p>Switch to a fallback for the chat-assistant layer in the <a href="./../../TOOLS.html">Tool Handout</a>: <strong>Claude (Artifacts)</strong> has a live preview (18+ only); <strong>ChatGPT</strong> gives code you run yourself (<a href="#no-preview-run-it-yourself">No preview? Run it yourself</a>). The prompts in this lab work unchanged. If you switch partway, paste your current code into the new chat first: the new tool starts with an empty context window.</p>`,96)])])}const m=e(s,[["render",r]]);export{p as __pageData,m as default};
